package control

import (
	"encoding/json"
	"os"
	"testing"

	"multiple-protocol-controller/internal/config"
)

// productContractArtifact is generated by the backend test
// iot-platform-backend/internal/handler/datatype_contract_artifact_test.go from
// the production gin route's response bytes. The runtime config test consumes
// that exact JSON instead of a hand-written protocol fixture.
const productContractArtifact = "../../../documents/integration/datatype-contract/product-create-success.json"

func TestBackendHTTPContractArtifactBuildsExpectedRuntimeTypes(t *testing.T) {
	if _, err := os.Stat("../../../documents/integration/datatype-contract"); err != nil {
		t.Skip("workspace contract artifacts are unavailable; see documents/integration/datatype-contract/README.md")
	}
	raw, err := os.ReadFile(productContractArtifact)
	if err != nil {
		t.Fatalf("read backend HTTP artifact: %v", err)
	}
	var envelope struct {
		Data struct {
			Properties []config.Property `json:"properties"`
		} `json:"data"`
	}
	if err := json.Unmarshal(raw, &envelope); err != nil {
		t.Fatalf("decode backend HTTP artifact: %v", err)
	}
	if len(envelope.Data.Properties) != 1 {
		t.Fatalf("artifact properties = %d, want 1", len(envelope.Data.Properties))
	}

	device := config.DeviceConfig{
		ID:           "device-contract-1",
		SerialNumber: "SN-CONTRACT",
		Protocol:     "MODBUS_RTU",
		AcqFreq:      1000,
		Properties:   envelope.Data.Properties,
		Params: []config.DeviceParam{{
			Label: "从机ID", Key: "slaveID", Type: "string", Value: json.RawMessage(`"1"`),
		}},
	}
	device.GatewayInfo.ID = "gateway-contract-1"
	device.GatewayInfo.IP = "127.0.0.1"
	device.GatewayInfo.Port = 502

	runtime, err := config.BuildRuntimeConfig([]config.DeviceConfig{device})
	if err != nil {
		t.Fatalf("BuildRuntimeConfig() error = %v", err)
	}
	rt, ok := runtime.DeviceBySerial["SN-CONTRACT"]
	if !ok {
		t.Fatal("artifact device is missing from the runtime config")
	}
	if len(rt.ReadPoints) != 2 {
		t.Fatalf("read points = %d, want 2", len(rt.ReadPoints))
	}
	for index, want := range []struct {
		propertyType string
		dataType     string
		quantity     int
	}{
		{"float", "uint16", 1},
		{"float", "float32", 2},
	} {
		point := rt.ReadPoints[index]
		if point.PropertyType != want.propertyType || point.DataType != want.dataType ||
			!point.DataTypeExplicit || point.Quantity != want.quantity {
			t.Fatalf("read point %d = {propertyType:%q dataType:%q explicit:%v quantity:%d}, want %+v",
				index, point.PropertyType, point.DataType, point.DataTypeExplicit, point.Quantity, want)
		}
	}

	commands := runtime.DeviceCmdBySerial["SN-CONTRACT"]
	if len(commands) != 1 {
		t.Fatalf("write commands = %d, want 1", len(commands))
	}
	command := commands[0]
	if command.PropertyType != "float" || command.DataType != "int64" ||
		!command.DataTypeExplicit || command.FunctionCode != 16 || command.Quantity != 4 {
		t.Fatalf("write command = {propertyType:%q dataType:%q explicit:%v functionCode:%d quantity:%d}, want float/int64/true/16/4",
			command.PropertyType, command.DataType, command.DataTypeExplicit, command.FunctionCode, command.Quantity)
	}

	// The explicit flag drives the strict conversion: the same json.Number that
	// the control decoder now produces is preserved exactly for int64.
	value, err := normalizeCommandValue(command.DataType, command.DataTypeExplicit, json.Number("9007199254740993"))
	if err != nil {
		t.Fatalf("normalizeCommandValue() error = %v", err)
	}
	if got, ok := value.(int64); !ok || got != 9007199254740993 {
		t.Fatalf("normalized int64 = %#v, want 9007199254740993", value)
	}
}
